void solve(int CASE)
{
    ll n, m; cin >> n >> m;
    var s = vector<int>(n + 1);
    var c = vector<ll>(n + 1);
    var d = vector<ll>(n + 1);
    var val = vector<ll>(n + 1);
    var sol = vector<bool>(n + 1);
    fa(i, 1, n)s[i] = i, c[i] = 0, d[i] = 1;

    var find = [&](var find, int x)->int {
        if (s[x] == x)return x;
        int root = find(find, s[x]);
        c[x] += d[x] * c[s[x]];
        d[x] *= d[s[x]];
        return s[x] = root;
        };

    ll k = 0;
    var yes = [&]()->void { cout << "Yes" << endl; k++; };
    var no =  [&]()->void { cout << "No" << endl; };

    while (m--) {
        ll aa, bb, dd; cin >> aa >> bb >> dd;
        ll i = (aa + k - 1) % n + 1;
        ll j = (bb + k - 1) % n + 1;
        ll w = (dd + k) % mod + 1;
        w *= 2;

        if (i == j) {
            int e1 = find(find, i);
            if (sol[e1]) {
                ll now = d[i] * val[e1] + c[i];
                if (now == w / 2)yes();
                else no();
            }
            else {
                sol[e1] = 1;
                val[e1] = (w - (c[i] + c[j])) / 2 * d[i];
                yes();
            }
            continue;
        }

        int e1 = find(find, i), e2 = find(find, j);
        if (e1 == e2) {
            int d1 = d[i], d2 = d[j];
            if (d1 == d2) {
                ll need = (w - (c[i] + c[j])) / 2 * d1;
                if (sol[e1]) {
                    if (val[e1] == need)yes();
                    else no();
                }
                else {
                    sol[e1] = 1;
                    val[e1] = need;
                    yes();
                }
            }
            else {
                if (c[i] + c[j] == w)yes();
                else no();
            }
        }
        else {
            var merge = [&](int i, int j, int e1, int e2)->void {
                s[e2] = e1;
                c[e2] = d[j] * (w - c[i] - c[j]);
                d[e2] = -d[i] * d[j];
                yes();
                };
            if (sol[e1] and sol[e2]) {
                if (c[i] + val[e1] * d[i] + c[j] + val[e2] * d[j] == w)yes();
                else no();
            }
            else if (sol[e1])merge(i, j, e1, e2);
            else if (sol[e2])merge(j, i, e2, e1);
            else merge(i, j, e1, e2);
        }
    }
    return;
}
